from datetime import datetimefrom sqlalchemy import Column, Integer, String, DateTime, Text, Boolean, Floatfrom .database import Baseclass User(Base):    __tablename__ = "users"    id = Column(Integer, primary_key=True)    username = Column(String(64), unique=True, nullable=False)    password_hash = Column(String(128), nullable=False)    role = Column(String(16), default="user", nullable=False)    is_protected = Column(Boolean, default=False, nullable=False)    def summary(self):        return {            "id": self.id, "username": self.username, "role": self.role,            "is_protected": bool(self.is_protected),        }class Scan(Base):    __tablename__ = "scans"    id = Column(Integer, primary_key=True)    image = Column(String(512), nullable=False)    status = Column(String(16), default="pending")    error = Column(Text, nullable=True)    created_at = Column(DateTime, default=datetime.utcnow)    finished_at = Column(DateTime, nullable=True)    critical = Column(Integer, default=0)    high = Column(Integer, default=0)    medium = Column(Integer, default=0)    low = Column(Integer, default=0)    unknown = Column(Integer, default=0)    result_json = Column(Text, nullable=True)    log = Column(Text, nullable=True)    secrets_enabled = Column(Boolean, default=False)    secrets_found = Column(Integer, default=0)    created_by = Column(String(64), nullable=True)    def summary(self):        return {            "id": self.id, "image": self.image, "status": self.status,            "error": self.error,            "created_at": self.created_at.isoformat() if self.created_at else None,            "finished_at": self.finished_at.isoformat() if self.finished_at else None,            "critical": self.critical, "high": self.high, "medium": self.medium,            "low": self.low, "unknown": self.unknown,            "secrets_enabled": bool(self.secrets_enabled),            "secrets_found": self.secrets_found,            "created_by": self.created_by,        }class AuditLog(Base):    __tablename__ = "audit_logs"    id = Column(Integer, primary_key=True)    created_at = Column(DateTime, default=datetime.utcnow, index=True)    username = Column(String(64), nullable=False, index=True)    action = Column(String(64), nullable=False, index=True)    target = Column(String(512), nullable=True)    details = Column(Text, nullable=True)    ip = Column(String(64), nullable=True)    def summary(self):        return {            "id": self.id,            "created_at": self.created_at.isoformat() if self.created_at else None,            "username": self.username,            "action": self.action,            "target": self.target,            "details": self.details,            "ip": self.ip,        }class EpssScore(Base):    __tablename__ = "epss_scores"    cve = Column(String(32), primary_key=True)    epss = Column(Float, default=0)    percentile = Column(Float, default=0)class KevEntry(Base):    __tablename__ = "kev_entries"    cve = Column(String(32), primary_key=True)    vendor = Column(String(256), nullable=True)    product = Column(String(256), nullable=True)    name = Column(String(512), nullable=True)    date_added = Column(String(16), nullable=True)    ransomware = Column(String(32), nullable=True)    due_date = Column(String(16), nullable=True)class FeedMeta(Base):    __tablename__ = "feed_meta"    name = Column(String(32), primary_key=True)    updated_at = Column(DateTime, nullable=True)    extra = Column(String(256), nullable=True)